const body = $input.first().json.body || $input.first().json;

if (!body?.data?.message) return [];

const data = body.data;
if (data.key?.fromMe === true) return [];

const remoteJid = data.key?.remoteJid || '';
if (remoteJid.includes('@g.us') || remoteJid.match(/\d+-\d+@/)) return [];

const mensaje = data.message?.conversation ||
                data.message?.extendedTextMessage?.text ||
                data.message?.imageMessage?.caption || '';
if (!mensaje.trim()) return [];

const numero = remoteJid.replace('@s.whatsapp.net','').replace('@lid','');
const nombre  = data.pushName || 'Cliente';
const instancia = body.instance || data.owner || '';
const ciudad = 'bogota';

const ctxInfo = data.message?.extendedTextMessage?.contextInfo;
const isFromAd = !!(ctxInfo?.externalAdReply || data.message?.advertisementReplyMessage || data.referral);

return [{ json: { numero, mensaje: mensaje.trim(), nombre, instancia, ciudad, isFromAd } }];

const { numero, mensaje, nombre, instancia, ciudad, isFromAd } = $input.first().json;

// ⚠️ MODO PRUEBA — botActivo siempre true. Restaurar horario real antes de producción.
const botActivo = true;

/* HORARIO PRODUCCIÓN BOGOTÁ — descomentar cuando salga a producción:
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Bogota' }));
const day = now.getDay(); // 0=Dom, 1=Lun, ..., 6=Sab
const t = now.getHours() * 60 + now.getMinutes();
const T = (h) => h * 60;
let botActivo = false;
if (day >= 1 && day <= 4) botActivo = t >= T(22) || t < T(8);  // Lun-Jue: 22:00-08:00
else if (day === 5)        botActivo = t >= T(18) || t < T(8);  // Vie: 18:00-08:00
else if (day === 6)        botActivo = t >= T(17) || t < T(9);  // Sab: 17:00-09:00
else if (day === 0)        botActivo = t >= T(16) || t < T(8);  // Dom: 16:00-08:00
*/

return [{ json: { numero, mensaje, nombre, instancia, ciudad, isFromAd, botActivo } }];

const searchTerm = query;
let token;
try {
  const authBody = JSON.stringify({
    username: 'ferreteriayacom@gmail.com',
    access_key: 'MGJkNGY1N2MtNDgyNC00NjI1LWIyY2MtZmMwMDMzNTcwNWE5Oj1xKDg4Nj1mclQ='
  });
  const auth = await $helpers.httpRequest({
    method: 'POST',
    url: 'https://api.siigo.com/auth',
    headers: {
      'Content-Type': 'application/json',
      'partner_id': 'ferreteriayasiigo'
    },
    body: authBody
  });
  token = auth.access_token;
} catch(e) {
  return 'Error autenticando Siigo: ' + e.message;
}
try {
  const resp = await $helpers.httpRequest({
    method: 'GET',
    url: 'https://api.siigo.com/v1/products?page_size=10&type=Product&search=' + encodeURIComponent(searchTerm),
    headers: {
      'Authorization': 'Bearer ' + token,
      'partner_id': 'ferreteriayasiigo'
    }
  });
  const results = (resp.results || []).filter(function(p) { return p.active; }).slice(0, 6);
  if (!results.length) return 'Producto no encontrado en catalogo para: ' + searchTerm;
  return results.map(function(p) {
    const priceVal = (p.prices && p.prices[0] && p.prices[0].price_list && p.prices[0].price_list[0])
      ? p.prices[0].price_list[0].value : null;
    const price = priceVal ? ' | Precio: $' + Number(priceVal).toLocaleString('es-CO') : ' | Sin precio registrado';
    return '- ' + p.name + price;
  }).join('\n');
} catch(e) {
  return 'Error consultando catalogo: ' + e.message;
}

